def angka_terbesar(*angka: float) -> float:
    """Mengembalikan angka terbesar dari sejumlah angka yang diberikan."""
    if not angka:
        raise ValueError("minimal satu angka harus diberikan")
    hasil = angka[0]
    for n in angka[1:]:
        if n > hasil:
            hasil = n
