def faktorial(n: int) -> int:
    """n! iteratif, O(n) waktu, aman untuk n besar tanpa recursion limit."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("n harus bilangan bulat non-negatif")
    hasil = 1
    for i in range(2, n + 1):
        hasil *= i
    return hasil


