from typing import Generator


def bilangan(mulai: int = 1, akhir: int = 10) -> Generator[int, None, None]:
    """Generator malas (lazy) untuk deret bilangan mulai..akhir, hemat memori untuk rentang besar."""
    if mulai > akhir:
        raise ValueError("mulai tidak boleh lebih besar dari akhir")
    yield from range(mulai, akhir + 1)


def format_bilangan(mulai: int = 1, akhir: int = 10) -> str:
    """Memformat hasil generator bilangan menjadi string dipisah spasi."""
    return " ".join(map(str, bilangan(mulai, akhir)))


