from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class RentangBilangan:
    mulai: int = 1
    akhir: int = 10

    def __post_init__(self):
        if self.mulai > self.akhir:
            raise ValueError("mulai tidak boleh lebih besar dari akhir")

    def __str__(self) -> str:
        return " ".join(map(str, range(self.mulai, self.akhir + 1)))


