def sum_list(numbers):
    """Sum numeric list; raises ValueError on empty and TypeError on bad type."""
    if not numbers:
        return 0
    if not all(isinstance(n, (int, float)) and not isinstance(n, bool) for n in numbers):
        raise TypeError("List must contain only int/float (bool excluded)")
    return sum(numbers)

