def find_max(numbers):
    """Find max via single-pass comparison; explicit and allocation-free."""
    it = iter(numbers)
    try:
        maksimum = next(it)
    except StopIteration:
        raise ValueError("numbers must not be empty")
    for n in it:
        if n > maksimum:
            maksimum = n
    return maksimum

print("Nilai terbesar dari [2,5,1,9] adalah", find_max([2, 5, 1, 9]))

def find_max(numbers) -> int | float:
    """Find max value; supports generators/iterators, not just lists."""
    maksimum = None
    for n in numbers:
        if maksimum is None or n > maksimum:
            maksimum = n
    if maksimum is None:
        raise ValueError("numbers must not be empty")
    return maksimum

