def find_max(numbers, key=lambda x: x):
    """Find max element by a key function, similar to built-in max(key=...)."""
    it = iter(numbers)
    maksimum = next(it)
    for n in it:
        if key(n) > key(maksimum):
            maksimum = n
    return maksimum

print("Nilai terbesar dari [2,5,1,9] adalah", find_max([2, 5, 1, 9]))

def find_max(numbers):
    """Find max; raises clear error on empty input, O(n) time O(1) space."""
    if not numbers:
        raise ValueError("numbers must not be empty")
    maksimum = numbers[0]
    for n in numbers[1:]:
        maksimum = n if n > maksimum else maksimum
    return maksimum

print("Nilai terbesar dari [2,5,1,9] adalah", find_max([2, 5, 1, 9]))

