    """Menentukan jenis bidang berdasarkan panjang dan lebar."""
    return "sama sisi" if panjang == lebar else "persegi panjang"


def main() -> None:
    try:
        panjang = float(input("Masukkan panjang: "))
        lebar = float(input("Masukkan lebar: "))
    except ValueError:
        print("Input harus berupa angka", file=sys.stderr)
        return
    print(cek_bentuk(panjang, lebar))


if __name__ == "__main__":
    main()

from typing import NamedTuple


class Dimensi(NamedTuple):
    panjang: float
    lebar: float


def cek_bentuk(dimensi: Dimensi) -> str:
    """Menentukan jenis bidang dari objek Dimensi."""
    return "sama sisi" if dimensi.panjang == dimensi.lebar else "persegi panjang"


def main() -> None:
    panjang = float(input("Masukkan panjang: "))
    lebar = float(input("Masukkan lebar: "))
    print(cek_bentuk(Dimensi(panjang, lebar)))


if __name__ == "__main__":
