def terbesar(a: float, b: float) -> float:
    """Kembalikan bilangan yang lebih besar di antara a dan b.

    Args:
        a: bilangan pertama.
        b: bilangan kedua.

    Returns:
        Nilai terbesar dari a dan b.
    """
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError("Parameter harus berupa angka (int/float)")
    return max(a, b)


