from dataclasses import dataclass

@dataclass(frozen=True)
class HasilPerbandingan:
    a: float
    b: float
    terbesar: float

def bandingkan(a: float, b: float) -> HasilPerbandingan:
    """Bandingkan dua bilangan dan kembalikan objek berisi hasilnya."""
    return HasilPerbandingan(a=a, b=b, terbesar=a if a >= b else b)

hasil = bandingkan(15, 27)
print(hasil.terbesar)

def terbesar(a: float, b: float) -> float:
    """Kembalikan bilangan terbesar dari a dan b menggunakan operator max Python.

    Menggunakan max() bawaan lebih disarankan karena teroptimasi secara internal
    dan lebih idiomatis dibanding perbandingan manual dengan if-else.
    """
    for nilai in (a, b):
        if not isinstance(nilai, (int, float)):
            raise TypeError(f"Nilai {nilai!r} bukan bilangan yang valid")
    return max(a, b)

print(terbesar(15, 27))

def terbesar(a: float, b: float) -> float:
    """Kembalikan bilangan terbesar dari a dan b (stabil untuk NaN dihindari)."""
    import math
    if isinstance(a, float) and math.isnan(a):
        return b
    if isinstance(b, float) and math.isnan(b):
        return a
    return a if a >= b else b

print(terbesar(15, 27))

def terbesar(a: float, b: float) -> float:
    """Kembalikan bilangan terbesar dari a dan b.

    Fungsi ini murni (pure function): tidak ada efek samping seperti
    print(), sehingga aman dipakai ulang di konteks apa pun.
    """
    if a >= b:
        return a
    return b


