from functools import total_ordering
from dataclasses import dataclass


@total_ordering
@dataclass
class Bilangan:
    nilai: float

    def __eq__(self, other):
        return self.nilai == other.nilai

    def __lt__(self, other):
        return self.nilai < other.nilai


def terbesar(a: float, b: float) -> float:
    """Kembalikan bilangan terbesar; didemonstrasikan lewat wrapper Bilangan."""
    bil_a, bil_b = Bilangan(a), Bilangan(b)
    return (bil_a if bil_a >= bil_b else bil_b).nilai


print(terbesar(15, 27))
